#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The fresh Jetson wizard: from a blank microSD card to an Orin Nano Super this laptop reaches over SSH with a key.
# jetson/wizard.sh then runs the probe, the install and the session.
#
#   bash jetson/provision.sh          from Git Bash on the laptop
#
# It downloads NVIDIA's JetPack 6.2.1 SD card image, has balenaEtcher (or Raspberry Pi Imager) write it to the card,
# walks the first boot and the setup screens on the board (the one place a monitor and keyboard are needed), then
# connects, puts this laptop's SSH key on the board, checks the board and records its facts in
# verification/jetson_facts.txt. If the board's firmware is too old for JetPack 6, stage 5 walks NVIDIA's one-time
# update through JetPack 5.1.3 first. The host, the user and the other values are kept in jetson/.env (git-ignored by
# the repo's .env rule), where jetson/wizard.sh reads J_HOST and J_USER. Run it again at any time: when the board is
# set up and on the network, stage 1 skips to the connection.

run_wizard() {

TOTAL_STAGES=8

STUDY="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$STUDY"
[[ "$ENV_FILE" == ".env" ]] && ENV_FILE="$STUDY/jetson/.env"
FACTS="verification/jetson_facts.txt"
KEY="$HOME/.ssh/id_ed25519"
HOTSPOT="ms-settings:network-mobilehotspot"
JP_PAGE="https://developer.nvidia.com/embedded/jetpack-sdk-621"
JP_URL="https://developer.nvidia.com/downloads/embedded/L4T/r36_Release_v4.4/jp62-r1-orin-nano-sd-card-image.zip"
JP_NAME="jp62-r1-orin-nano-sd-card-image.zip"
JP5_PAGE="https://developer.nvidia.com/embedded/jetpack-sdk-513"
JP5_NAME="JP513-orin-nano-sd-card-image_b29.zip"
UPDATE_PATH="https://docs.nvidia.com/jetson/orin-nano-devkit/user-guide/latest/update_firmware.html"
die()  { warn "$1"; exit 1; }
next() { pause "Press Enter for the next stage"; }
good() { say "${GREEN}✓${RESET} $1"; }
BAD=0
bad()  { warn "$1"; BAD=$((BAD + 1)); }
winpath() { cygpath -w "$1" 2>/dev/null || printf '%s' "$1"; }
# substage "Name": a new screen inside the current stage (stage 5 is four screens), with the same stage number.
substage() { _clear; printf '\n%s%s▸ Stage %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"; }

# ssh_try HOST: SSH with this laptop's key alone works. A fresh card's host key is accepted; SSH_ERR keeps ssh's message.
SSH_ERR=""
ssh_try() {
  SSH_ERR=$(ssh -n -o BatchMode=yes -o ConnectTimeout=8 -o StrictHostKeyChecking=accept-new "$J_USER@$1" true 2>&1 >/dev/null) && return 0
  return 1
}
# reach HOST: ssh_try, and when the board answers but has not got the key yet (the normal case on a fresh card), offer
# to copy the key with the board's password (once).
NO_COPY=""
reach() {
  ssh_try "$1" && return 0
  [[ "$SSH_ERR" == *"Permission denied"* && -z "$NO_COPY" ]] || return 1
  printf '\n'
  say "$1 answers SSH, but this laptop's key is not on it yet."
  confirm "Copy the key there now? You type the password you chose on the board's setup screen." || { NO_COPY=1; return 1; }
  ssh-copy-id -o StrictHostKeyChecking=accept-new -i "$KEY.pub" "$J_USER@$1" || true
  ssh_try "$1"
}
# forget_key HOST drops a saved host key for HOST: a freshly written card has new host keys, so a saved one is stale.
forget_key() {
  if ssh-keygen -F "$1" >/dev/null 2>&1; then
    ssh-keygen -R "$1" >/dev/null 2>&1 || true
    note "removed the old host key for $1 from ~/.ssh/known_hosts (the new card has new ones)"
  fi
}
# find_jetsons prints the IPs, on this laptop's hotspot or home network, that answer on port 22 with an Ubuntu SSH
# banner (Jetson Linux 36 is Ubuntu 22.04). It does not filter by MAC: it pings every address of each /24 once, so the ARP
# table learns who is there, then reads each host's SSH banner. The VPNs' addresses (Tailscale 100.x, WARP 172.16.x) are
# not swept; on the laptop's hotspot only its own 192.168.137.x is.
find_jetsons() {
  local nets s i ip nets_s
  if [[ "${J_NET:-}" == 1 ]]; then
    nets="192.168.137"
  else
    nets=$(ipconfig 2>/dev/null | tr -d '\r' | sed -n 's/.*IPv4 Address[. ]*: *\([0-9.]*\).*/\1/p' \
           | grep -E '^(192\.168\.|10\.|172\.20\.10\.)' | cut -d. -f1-3 | sort -u || true)
  fi
  for s in $nets; do
    for i in $(seq 254); do ping -n 1 -w 400 "$s.$i" >/dev/null 2>&1 & done
    wait
  done
  nets_s=$(printf '%s ' $nets)
  for ip in $(arp -a 2>/dev/null | tr -d '\r' \
              | awk -v nets="$nets_s" 'BEGIN { n = split(nets, a, " ") }
                  tolower($2) ~ /^[0-9a-f][0-9a-f]-/ && tolower($2) != "ff-ff-ff-ff-ff-ff" && tolower($2) !~ /^01-00-5e/ {
                    for (i = 1; i <= n; i++) if (index($1, a[i] ".") == 1 && $1 !~ /\.255$/) print $1 }' | sort -u || true); do
    {
      b=$(timeout 4 bash -c 'exec 3<>/dev/tcp/$0/22 && { IFS= read -r -t 3 l <&3; printf "%s" "$l"; }' "$ip" 2>/dev/null) || b=""
      if [[ "$b" == *Ubuntu* ]]; then printf '%s\n' "$ip"; fi
    } &
  done
  wait
}
# search_jetson: find_jetsons, then SSH to each; HOST is the one that takes this laptop's key.
search_jetson() {
  local ip
  local -a ips=()
  say "Looking for the board on the network (about 20 s)..."
  mapfile -t ips < <(find_jetsons)
  for ip in ${ips[@]+"${ips[@]}"}; do
    if [[ -n "$FRESH" ]]; then forget_key "$ip"; fi
    if reach "$ip"; then HOST="$ip"; good "found it at $ip"; return 0; fi
    note "a host at $ip answers SSH like an Ubuntu board, but not with this laptop's key: $(printf '%s\n' "${SSH_ERR:-}" | tail -n1)"
  done
  return 1
}
find_imager() {
  local p
  for p in "/c/Program Files/Raspberry Pi Imager/rpi-imager.exe" "/c/Program Files (x86)/Raspberry Pi Imager/rpi-imager.exe"; do
    [[ -f "$p" ]] && { printf '%s' "$p"; return 0; }
  done
  return 1
}
find_etcher() {
  local p
  for p in "$HOME/AppData/Local/Programs/balena-etcher/balenaEtcher.exe" "/c/Program Files/balenaEtcher/balenaEtcher.exe"; do
    [[ -f "$p" ]] && { printf '%s' "$p"; return 0; }
  done
  return 1
}
# remote_size URL prints the size in bytes of the file at URL, or nothing when the server gives no file (a login page,
# an error): a HEAD request first, then a one-byte range request for servers that refuse HEAD.
remote_size() {
  local h n
  h=$(curl -sIL --max-time 30 "$1" 2>/dev/null | tr -d '\r') || h=""
  n=$(printf '%s\n' "$h" | awk '/^HTTP/ {s=$2; n=""} tolower($1)=="content-length:" {n=$2} END {if (s==200 && n ~ /^[0-9]+$/) print n}')
  if [[ -z "$n" ]]; then
    h=$(curl -sL --max-time 30 -r 0-0 -D - -o /dev/null "$1" 2>/dev/null | tr -d '\r') || h=""
    n=$(printf '%s\n' "$h" | awk '/^HTTP/ {s=$2; n=""} tolower($1)=="content-range:" {split($3, a, "/"); n=a[2]} END {if (s==206 && n ~ /^[0-9]+$/) print n}')
  fi
  printf '%s' "$n"
}
local_size() { if [[ -f "$1" ]]; then stat -c %s "$1"; else printf '0'; fi; }
# locate_zip PATTERN... prints the newest file in the download folder named like one of the PATTERNs, or nothing.
locate_zip() {
  local -a pats=(-iname "$1"); shift
  while (( $# )); do pats+=(-o -iname "$1"); shift; done
  find "$J_DL" -maxdepth 1 -type f \( "${pats[@]}" \) -printf '%T@ %p\n' 2>/dev/null | sort -rn | head -n1 | cut -d' ' -f2- || true
}
# flash_steps ZIP: the clicks that write ZIP to the card, in the tool picked in stage 3.
flash_steps() {
  local zip; zip=$(winpath "$1")
  if [[ "$TOOL" == 1 ]]; then
    step "In balenaEtcher, click 'Flash from file' and pick: $zip"
    step "Click 'Select target', tick the SD card only, and check its size and name against your card. Click 'Select'."
    step "Click 'Flash!'. Windows asks whether it may make changes: Yes. Wait for the write and its validation (10-20 minutes)."
  else
    # Imager reads a .zip holding an .img through libarchive (its source; findings/39 item 1); not yet tried on this 24 GB image
    step "In Imager, 'Choose Device': pick any (the choice does not change a custom image). Next."
    step "'Choose OS': scroll to the bottom and click 'Use custom', then pick: $zip"
    step "'Choose Storage': the SD card only. Check its size and name against your card. Next."
    step "If Imager offers to edit settings (customisation), choose No: it cannot customise NVIDIA's image."
    step "Write, and confirm that the card is erased. Wait for the write and its verification (10-20 minutes)."
  fi
  step "If Windows then says 'You need to format the disk': click Cancel. Take the card out."
}

banner "A fresh Jetson Orin Nano Super: from a blank microSD card to SSH"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "What you need"
say "This wizard sets the Jetson up from a blank microSD card. Then jetson/wizard.sh takes it through the sessions."
say "Have these ready:"
step "The Orin Nano Super Developer Kit and its 19 V power supply."
step "A microSD card of 64 GB or more (UHS-I; NVIDIA recommends 64 GB UHS-1 or larger), and a card reader for this laptop."
note "The image writes 24 GB, so a 32 GB card is the very least, and a 16 GB card cannot work."
step "A DisplayPort monitor (or a DisplayPort-to-HDMI adapter) and a USB keyboard and mouse. The first boot needs them once."
step "A network with plain internet: this laptop's Mobile Hotspot (recommended) or Ethernet."
note "Campus Wi-Fi that shows a login page (such as amritanet.edu) does not work: the board cannot log in to it."
step "About an hour: the download and the card write take most of it."
FRESH=1
if confirm "Is the board already set up, and on the network? (yes skips to the connection)"; then
  FRESH=""
  _STAGE_INDEX=6
else
  warn "Writing the card erases everything on it."
  confirm "Ready to download and write the card?" || { say "Run it again when you are: bash jetson/provision.sh"; exit 0; }
fi

if [[ -n "$FRESH" ]]; then

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Download JetPack 6.2.1"
say "The card gets NVIDIA's JetPack 6.2.1 SD card image: $JP_NAME"
note "NVIDIA's download page now offers JetPack 7.2.1 first. Do not take it: it is L4T R39 on Ubuntu 24.04 with CUDA 13,"
note "and the study's probe (#11) cuts anything but JetPack 6. PLATFORMS.md's pins are for JetPack 6."
DL_DEF=$(_existing J_DL || true)
[[ -n "$DL_DEF" ]] || DL_DEF="$HOME/Downloads"
J_DL="$DL_DEF"
ask J_DL "A folder to download into [$DL_DEF]:" || true
[[ -n "$J_DL" ]] || J_DL="$DL_DEF"
if [[ "$J_DL" == *\\* ]]; then J_DL=$(cygpath -u "$J_DL"); fi
J_DL="${J_DL%/}"
mkdir -p "$J_DL" || die "cannot make the folder $J_DL: run the wizard again with another one"
write_env J_DL "$J_DL"
JP_ZIP="$J_DL/$JP_NAME"
say "Asking NVIDIA for the file's size..."
# The URL needs no NVIDIA login (checked 2026-10-29). If that changes, a login page makes remote_size print nothing,
# and the manual route below takes over.
REMOTE=$(remote_size "$JP_URL")
# The server says the image is 11.7 GB (checked 2026-10-29); the 100 MB test only tells a real image from a login or error page.
if [[ -n "$REMOTE" ]] && (( REMOTE > 100000000 )); then
  say "The image is $(( REMOTE / 1048576 )) MB."
  if [[ "$(local_size "$JP_ZIP")" == "$REMOTE" ]]; then
    good "already downloaded: $JP_ZIP"
  else
    FREE_K=$(df -Pk "$J_DL" 2>/dev/null | awk 'NR==2 {print $4}')
    [[ "$FREE_K" =~ ^[0-9]+$ ]] || FREE_K=""
    if [[ -n "$FREE_K" ]] && (( FREE_K * 1024 < REMOTE + 3221225472 )); then
      die "only $(( FREE_K / 1048576 )) GB free in $J_DL, and the image needs about $(( (REMOTE + 3221225472) / 1073741824 )) GB: free some space or pick another folder, then run the wizard again"
    fi
    say "Downloading to $JP_ZIP. If it stops, run the wizard again: it resumes where it left off."
    while true; do
      curl -fL -C - -o "$JP_ZIP" "$JP_URL" && break
      warn "the download stopped."
      confirm "Resume it?" || die "run the wizard again to resume the download"
    done
    [[ "$(local_size "$JP_ZIP")" == "$REMOTE" ]] || die "the file is $(local_size "$JP_ZIP") bytes, not the $REMOTE the server says: delete $JP_ZIP and run the wizard again"
    good "downloaded: $JP_ZIP"
  fi
else
  warn "NVIDIA's server does not give the file straight away (it may want a login). Download it in the browser instead."
  open_url "$JP_PAGE"
  step "Find 'Jetson Orin Nano Developer Kit' under the JetPack 6.2.1 downloads and click the SD card image: $JP_NAME"
  step "Sign in with a free NVIDIA account if it asks, and accept the terms."
  step "Save the file in $(winpath "$J_DL")"
  pause "Press Enter when the download has finished"
  JP_ZIP=$(locate_zip 'jp62-r1-orin-nano-sd-card-image*.zip' 'jetson-orin-nano-devkit-super-SD-image_JP6.2.1*.zip')
  while [[ -z "$JP_ZIP" || ! -f "$JP_ZIP" ]]; do
    warn "no $JP_NAME in $J_DL yet."
    ask JP_ZIP "The full path of the zip (q stops here):" || JP_ZIP=q
    [[ "$JP_ZIP" != q ]] || die "no image yet: run the wizard again when it is downloaded"
    if [[ "$JP_ZIP" == *\\* ]]; then JP_ZIP=$(cygpath -u "$JP_ZIP"); fi
  done
  good "found it: $JP_ZIP"
fi
next

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Write the card"
warn "Writing erases everything on the card. Check the card's size before you choose it, and never pick a disk you do not recognise."
IMAGER=$(find_imager || true)
ETCHER=$(find_etcher || true)
say "Two tools can write the image:"
say "  1) balenaEtcher, the tool NVIDIA documents. $([[ -n "$ETCHER" ]] && echo 'Installed.' || echo 'Not installed yet.')"
say "  2) Raspberry Pi Imager, $([[ -n "$IMAGER" ]] && echo 'already on this laptop' || echo 'not installed'), with 'Use custom'. Not tried with this image yet."
ask TOOL "Which one, 1 or 2? (Enter for 1):" || TOOL=""
[[ -n "$TOOL" ]] || TOOL=1
[[ "$TOOL" == 1 || "$TOOL" == 2 ]] || die "answer 1 or 2: run the wizard again"
if [[ "$TOOL" == 1 ]]; then
  if [[ -z "$ETCHER" ]]; then
    say "balenaEtcher is not installed yet."
    open_url "https://etcher.balena.io/"
    step "Click the download for Windows, run the installer and keep its defaults."
    pause "Press Enter once Etcher is installed"
    ETCHER=$(find_etcher || true)
  fi
  PROG="$ETCHER"
else
  if [[ -z "$IMAGER" ]]; then
    say "Imager is not installed yet."
    open_url "https://www.raspberrypi.com/software/"
    step "Click 'Download for Windows', run the installer and keep its defaults."
    pause "Press Enter once Imager is installed"
    IMAGER=$(find_imager || true)
  fi
  PROG="$IMAGER"
fi
step "Put the microSD card in this laptop's reader."
if [[ -n "$PROG" ]] && powershell.exe -NoProfile -Command "Start-Process -FilePath '$(cygpath -w "$PROG")'" >/dev/null 2>&1; then
  say "Opening the tool. Windows may ask whether it may make changes: Yes."
else
  step "Open the tool from the Start menu."
fi
say "In it:"
flash_steps "$JP_ZIP"
pause "Press Enter when the card is written and out of the laptop"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "First boot"
step "Put the card in the slot on the underside of the module. It is the module (the board under the fan), not the carrier board."
step "Connect the monitor to the DisplayPort, and the keyboard and mouse to the USB ports. Plug in Ethernet if you use it."
step "Plug in the 19 V supply. The kit powers on by itself."
# With no monitor plugged in, NVIDIA's nv-oem-config.sh runs the text setup on the USB-C serial port instead
# (ttyGS0, 115200 8N1; findings/39 item 3). The monitor stays the main route; the serial one is a fallback.
note "A new card boots in 1-3 minutes."
note "No DisplayPort monitor at all? Boot with none plugged in and connect the board's USB-C port to this laptop: the setup"
note "then runs as text on a 'USB Serial Device (COMn)' in Device Manager. Open it in PuTTY: Serial, COMn, speed 115200."
printf '\n'
say "What does the screen show?"
say "  1) NVIDIA's license screen, then Ubuntu's setup screens. The firmware is new enough (36.x)."
say "  2) A black screen, a UEFI shell, or no boot after about 3 minutes. The firmware is older than 36.0."
note "To read the firmware version: press Esc again and again at the NVIDIA logo. The UEFI menu shows the version near the top."
ask FW_CHOICE "Which one, 1 or 2?" || FW_CHOICE=""
[[ "$FW_CHOICE" == 1 || "$FW_CHOICE" == 2 ]] || die "answer 1 or 2: run the wizard again"
if [[ "$FW_CHOICE" == 2 ]]; then write_env J_FW_OLD yes; else write_env J_FW_OLD no; fi
next

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "The firmware bridge"
if [[ "$J_FW_OLD" != yes ]]; then
  good "The firmware is new enough: there is nothing to do here."
  next
else
  say "JetPack 6 needs firmware 36.x. This board has an older one, so it takes NVIDIA's one-time update through JetPack 5.1.3."
  note "NVIDIA's 'JetPack 6.x Update Path': $UPDATE_PATH"
  # The steps of NVIDIA's update page, checked 2026-10-28 and 2026-10-29 (findings/39 item 2)
  say "About an hour. You type the commands on the board's own screen."
  printf '\n'
  say "Get the JetPack 5.1.3 image:"
  open_url "$JP5_PAGE"
  step "Download exactly $JP5_NAME (the 'b29' image; not an older JetPack 5.1.3 image), into $(winpath "$J_DL")"
  pause "Press Enter when the download has finished"
  JP5_ZIP=$(locate_zip 'JP513-orin-nano-sd-card-image_b29*.zip')
  while [[ -z "$JP5_ZIP" || ! -f "$JP5_ZIP" ]]; do
    warn "no $JP5_NAME in $J_DL yet."
    ask JP5_ZIP "The full path of the zip (q stops here):" || JP5_ZIP=q
    [[ "$JP5_ZIP" != q ]] || die "no JetPack 5.1.3 image yet: run the wizard again when it is downloaded"
    if [[ "$JP5_ZIP" == *\\* ]]; then JP5_ZIP=$(cygpath -u "$JP5_ZIP"); fi
  done
  good "found it: $JP5_ZIP"
  next

  substage "The firmware bridge: write JetPack 5.1.3"
  step "Power the board off: unplug the 19 V supply. Take the card out of the board and put it in this laptop's reader."
  say "Write the JetPack 5.1.3 image, with the same tool as before:"
  flash_steps "$JP5_ZIP"
  pause "Press Enter when the card is written and out of the laptop"

  substage "The firmware bridge: update the firmware"
  step "Put the card back in the board, and plug in the 19 V supply."
  step "Finish JetPack 5.1.3's setup screens with internet on (the Wi-Fi or Ethernet). Any user name and password: this install is temporary."
  step "Open a terminal on the board (Ctrl+Alt+T) and run: sudo systemctl status nv-l4t-bootloader-config"
  say "    It should show the firmware update as scheduled: 'inactive', with an exit status of success."
  step "Run: sudo reboot"
  say "    The firmware updates during this reboot, and the board then boots JetPack 5.1.3 again. Do not cut the power."
  step "In the terminal: sudo nvbootctrl dump-slots-info"
  say "    It should show: Current version: 35.5.0"
  pause "Press Enter when it shows 35.5.0"
  step "Run: sudo apt update && sudo apt install nvidia-l4t-jetson-orin-nano-qspi-updater"
  step "Run: sudo reboot"
  warn "Do NOT cut the power while the board updates: it can take several minutes, and cutting it can break the board."
  pause "Press Enter when the board has booted again"
  step "Power the board off: run 'sudo poweroff', then unplug the 19 V supply. Take the card out."

  substage "The firmware bridge: write JetPack 6.2.1"
  say "The firmware is now 36.x. Put the card in this laptop's reader and write the JetPack 6.2.1 image from stage 2:"
  flash_steps "$JP_ZIP"
  step "Put the card back in the board and plug in the 19 V supply."
  note "It should now show NVIDIA's license screen, then Ubuntu's setup screens."
  next
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The setup screens and the board's network"
ask J_NAME "A computer name for the board (letters, digits and hyphens; Enter for jetson):" || J_NAME=""
[[ -n "$J_NAME" ]] || J_NAME=jetson
[[ "$J_NAME" =~ ^[A-Za-z0-9-]+$ ]] || die "a host name has letters, digits and hyphens only: run the wizard again"
ask J_USER "The user to make on the board (lower case; Enter for jetson):" || J_USER=""
[[ -n "$J_USER" ]] || J_USER=jetson
[[ "$J_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || die "a user name has lower-case letters, digits, - and _ only: run the wizard again"
write_env J_NAME "$J_NAME"
write_env J_USER "$J_USER"
say "The board joins a network this laptop is on, with internet: jetson/wizard.sh's install downloads about 3 GB."
say "  1) this laptop's Mobile Hotspot. Recommended."
say "  2) Ethernet to a router, that this laptop is on too."
ask J_NET "Which one, 1 or 2?" || J_NET=""
[[ "$J_NET" == 1 || "$J_NET" == 2 ]] || die "answer 1 or 2: run the wizard again"
write_env J_NET "$J_NET"
if [[ "$J_NET" == 1 ]]; then
  open_url "$HOTSPOT"
  step "Turn Mobile hotspot on."
  step "Under Properties, click Edit, and note the network's name and password. If the board does not see the network, set the band to 2.4 GHz."
  step "Turn Power saving off, so the hotspot stays on while the board is the only device on it."
  note "Keep the hotspot on whenever you work with the board."
else
  step "Plug the Ethernet cable into the board and the router."
fi
pause "Press Enter when the network is ready"
printf '\n'
# NVIDIA lists the EULA, language, keyboard, time zone, network and user screens; the oem-config package adds the APP
# partition, swap and Chromium screens, in an order not documented. There is no power-mode screen (findings/39 item 3).
say "On the board's screen (the order may differ a little):"
step "Accept the NVIDIA license (EULA)."
step "Language: English. Keyboard layout: yours."
step "Time zone: Kolkata."
step "Your name: anything. Your computer's name: $J_NAME"
step "Your username: $J_USER"
step "A password you will remember. This wizard never asks for it: you type it to copy the SSH key, and for sudo."
step "APP partition size: leave it blank or 0, for the maximum: the system grows to the whole card."
step "Create SWAP file: Yes (4 GB). The INT8 engine builds can run out of memory without it."
step "Install Chromium: No."
note "There is no power-mode screen: the board starts in 25W, and jetson/wizard.sh sets MAXN SUPER later."
if [[ "$J_NET" == 1 ]]; then
  step "Network: join the hotspot's Wi-Fi with its name and password."
else
  step "Network: the Ethernet connection is used by itself."
fi
step "Let it finish. It restarts into the desktop; log in if asked. This takes a few minutes."
pause "Press Enter when you see the desktop"
printf '\n'
say "Then open a terminal on the board (Ctrl+Alt+T) and run:"
step "sudo systemctl status nv-l4t-bootloader-config"
say "    If it shows a firmware update scheduled (JetPack 6.2.x may schedule one), run 'sudo reboot' once and wait. Do not cut the power."
say "    Not sure what it shows? Reboot once anyway: it costs a minute."
# No NVIDIA page says openssh-server is on by default, though NVIDIA's own tutorials ssh in right after the setup
step "systemctl is-active ssh      (it should print: active)"
step "hostname -I                  (note the first address, like 192.168.137.xx)"
note "If ssh is not active: sudo apt install -y openssh-server"
BOARD_IP=""
ask BOARD_IP "The board's IP address from hostname -I (Enter if you did not note it):" || BOARD_IP=""
BOARD_IP="${BOARD_IP%% *}"
next

fi   # FRESH: stages 2-6

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Connect over SSH"
J_NET="${J_NET:-}"; BOARD_IP="${BOARD_IP:-}"; J_NAME="${J_NAME:-}"; J_USER="${J_USER:-}"
[[ -n "$J_NET" ]]  || J_NET=$(_existing J_NET || true)
[[ -n "$J_NAME" ]] || J_NAME=$(_existing J_NAME || true)
[[ -n "$J_USER" ]] || J_USER=$(_existing J_USER || true)
if [[ -z "$J_USER" ]]; then
  ask J_USER "The user on the board:" || J_USER=""
  [[ "$J_USER" =~ ^[a-z_][a-z0-9_-]*$ ]] || die "no user name: run the wizard again"
fi
write_env J_USER "$J_USER"
if [[ ! -f "$KEY.pub" ]]; then
  confirm "Make an SSH key on this laptop ($KEY, no passphrase)?" || die "the board needs this laptop's public key: run the wizard again"
  mkdir -p "$HOME/.ssh"
  ssh-keygen -t ed25519 -N "" -f "$KEY"
fi
say "This laptop's SSH key: $KEY.pub"
CANDS=()
if [[ -n "$J_NAME" ]]; then CANDS+=("$J_NAME.local"); fi
OLD=$(_existing J_HOST || true)
if [[ -n "$OLD" && "$OLD" != "$J_NAME.local" ]]; then CANDS+=("$OLD"); fi
if [[ -n "$BOARD_IP" && "$BOARD_IP" != "$OLD" ]]; then CANDS+=("$BOARD_IP"); fi
if [[ -n "$FRESH" ]]; then for h in ${CANDS[@]+"${CANDS[@]}"}; do forget_key "$h"; done; fi
HOST=""
if (( ${#CANDS[@]} )); then
  say "Trying $J_USER@${CANDS[*]} for about 3 minutes..."
  for _ in $(seq 18); do
    for h in "${CANDS[@]}"; do
      if reach "$h"; then HOST="$h"; break 2; fi
    done
    printf '.'
    sleep 10
  done
  printf '\n'
fi
if [[ -z "$HOST" ]]; then search_jetson || true; fi
while [[ -z "$HOST" ]]; do
  warn "no SSH yet: $(printf '%s\n' "${SSH_ERR:-no answer}" | tail -n1)"
  if [[ "$SSH_ERR" == *"IDENTIFICATION HAS CHANGED"* ]] \
     && confirm "The board's host keys changed (a newly written card?). Forget the old ones for ${CANDS[*]:-the board} and try again?"; then
    for h in ${CANDS[@]+"${CANDS[@]}"}; do forget_key "$h"; done
    for h in ${CANDS[@]+"${CANDS[@]}"}; do
      if reach "$h"; then HOST="$h"; break; fi
    done
    if [[ -n "$HOST" ]]; then break; fi
  fi
  if [[ "$SSH_ERR" == *"Connection refused"* ]]; then
    warn "The board answers, but its SSH server is not running."
    step "On the board's terminal: sudo apt install -y openssh-server"
    step "Then: sudo systemctl enable --now ssh"
  fi
  # The board's USB-C port is also a network to this laptop once the OS is up: the board is 192.168.55.1 and the laptop
  # gets 192.168.55.100 (findings/39 item 4). It is offered here, not tried in the loop above, where an address with no
  # cable would cost a timeout on every pass.
  if [[ -n "$J_NAME" ]]; then note "$J_NAME.local does not always work over Windows' hotspot: the IP address is the dependable route."; fi
  if [[ "$J_NET" == 1 ]]; then
    open_url "$HOTSPOT"
    step "Find '$J_NAME' under the hotspot's connected devices, and its IP address (192.168.137.x)."
  else
    step "Find the board's IP address in your router's list of devices."
  fi
  step "Or on the board's terminal: hostname -I"
  step "Or connect the board's USB-C port to this laptop with a data cable, wait 30 s, and type 192.168.55.1 below."
  note "  Over the cable alone the board has no internet: use it for SSH, and keep the hotspot or Ethernet for the install."
  note "Not on the network? Check the Wi-Fi icon at the top right of the board's desktop."
  ask BOARD_IP "The board's IP address (Enter searches the network again; q stops here):" || BOARD_IP=q
  [[ "$BOARD_IP" != q ]] || die "no connection yet: run bash jetson/provision.sh again (yes in stage 1 skips to here)"
  if [[ -z "$BOARD_IP" ]]; then search_jetson || true; continue; fi
  if [[ -n "$FRESH" ]]; then forget_key "$BOARD_IP"; fi
  if reach "$BOARD_IP"; then HOST="$BOARD_IP"; fi
done
write_env J_HOST "$HOST"
good "SSH with the key works: $J_USER@$J_HOST"

printf '\n'
say "Reading the board, its JetPack and its network..."
FACT=$(ssh -o ConnectTimeout=10 "$J_USER@$J_HOST" 'bash -s' <<'EOF' | tr -d '\r'
echo "date=$(date -Is)"
echo "model=$(tr -d '\0' < /proc/device-tree/model)"
echo "l4t=$(head -n1 /etc/nv_tegra_release 2>/dev/null)"
echo "kernel=$(uname -r)"
echo "arch=$(uname -m)"
echo "ram_mb=$(free -m | awk '/^Mem:/ {print $2}')"
echo "disk=$(df -h ~ | awk 'NR==2 {print $2 " total, " $4 " free"}')"
echo "disk_gb=$(df -BG --output=size ~ | tail -n1 | tr -dc 0-9)"
echo "internet=$(curl -s -o /dev/null -m 15 -w '%{http_code}' https://pypi.org/simple/ 2>/dev/null)"
EOF
) || die "lost the connection to the board: run the wizard again (yes in stage 1 skips to the connection)"
fact() { printf '%s\n' "$FACT" | sed -n "s/^$1=//p"; }

M=$(fact model)
if [[ "$M" == *"Orin Nano"* ]]; then good "Board: $M, $(fact ram_mb) MB RAM"; else bad "Board: ${M:-unreadable}. This is not a Jetson Orin Nano"; fi
L4T=$(fact l4t)
if [[ "$L4T" == *"R36"* ]]; then
  good "JetPack 6 (Jetson Linux 36): ${L4T:0:60}"
else
  bad "Jetson Linux: ${L4T:-unreadable}. The study needs JetPack 6 (R36): write the card again with the JetPack 6.2.1 image"
fi
good "Kernel $(fact kernel), $(fact arch)"
DISK=$(fact disk_gb)
if (( ${DISK:-0} >= 50 )); then
  good "Disk: $(fact disk)"
else
  bad "Disk: ${DISK:-?} GB. The install, the engines and the results need room: use a 64 GB card or larger"
fi
if [[ "$(fact internet)" == 200 ]]; then
  good "Internet: the board reaches PyPI"
else
  bad "The board cannot reach PyPI (HTTP $(fact internet)), and jetson/wizard.sh's install needs it. Is the network sharing this laptop's internet?"
fi
mkdir -p "$(dirname "$FACTS")"
{ printf '# The Jetson after a fresh card (jetson/provision.sh)\n'; printf '%s\n' "$FACT"; } > "$FACTS"
note "Recorded in study/$FACTS."
if (( BAD )); then
  warn "$BAD check(s) above need fixing before the sessions."
  confirm "Go on to the hand-over anyway?" || { say "Fix them, then run the wizard again (yes in stage 1 skips to the connection)."; exit 1; }
fi
next

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Hand over to the session wizard"
say "The board is ready for jetson/wizard.sh. Run from study/:"
step "bash jetson/wizard.sh"
say "It runs the probe (#11), sets the power mode, installs the pinned packages, copies the files, builds the 8 engines and"
say "starts the session. The engine builds and the session run on the board: you can close the wizard and come back."
note "Its stage 2 offers this host and user from jetson/.env: press Enter to keep them."
if confirm "Start it now?"; then
  exec bash "$STUDY/jetson/wizard.sh"
fi
finish
say "Next: bash jetson/wizard.sh"
}

run_wizard "$@"; exit
